# Get all ORFs >= 50 aa in both strands with proper coordinates, and rank by length
seq = open('region.fasta').read().split('\n',1)[1].replace('\n','').upper()
bases='TCAG'; aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
ct={b1+b2+b3:aas[i] for i,(b1,b2,b3) in enumerate((x,y,z) for x in bases for y in bases for z in bases)}
def tr(s): return ''.join(ct.get(s[j:j+3],'X') for j in range(0,len(s)-2,3))
def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]
L=len(seq)
results=[]
for name, strand in [('+', seq), ('-', rc(seq))]:
    for frame in range(3):
        prot = tr(strand[frame:])
        pos=0
        while pos < len(prot):
            j = prot.find('*', pos)
            end = len(prot) if j==-1 else j
            seg = prot[pos:end]
            if len(seg) >= 60:
                s1 = seg.find('M')
                if s1 != -1 and len(seg)-s1 >= 60:
                    nt_s = frame + (pos+s1)*3 + 1
                    nt_e = min(frame + end*3, L)
                    if name=='-':
                        cs, ce = L - nt_e + 1, L - nt_s + 1
                    else:
                        cs, ce = nt_s, nt_e
                    p = seg[s1:]
                    results.append(('ATG start', name, frame, cs, ce, len(p), p))
                if s1 not in (0,-1) or True:
                    nt_s = frame + pos*3 + 1
                    nt_e = min(frame + end*3, L)
                    if name=='-':
                        cs, ce = L - nt_e + 1, L - nt_s + 1
                    else:
                        cs, ce = nt_s, nt_e
                    results.append(('no start codon', name, frame, cs, ce, len(seg), seg))
            pos = end+1
for r in sorted(results, key=lambda x:-x[5])[:12]:
    print(r[1], 'nt', r[3], '-', r[4], 'aa_len', r[5], '| start codon present:', r[0]=='ATG start')
