def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]
L=len(seq)

# Revise ORF scored by SD motif (AGG, AGGA, etc.) upstream of a start codon
motif_scores = {}
best=[]
for name, strand in [('+', seq), ('-', rc(seq))]:
    for frame in range(3):
        prot = tr(strand[frame:])
        stops=[j for j,c in enumerate(prot) if c=='*']
        # create stop index map
        for j,c in enumerate(prot):
            if c=='M':
                # find next stop
                nxt = [k for k in stops if k>j]
                if not nxt: continue
                k = min(nxt)
                if k-j >= 50:
                    cs = frame + j*3 + 1
                    ce = min(frame + k*3, L)
                    if name=='-':
                        cs, ce = L-ce+1, L-cs+1
                  # SD-ish motif in nt cs-15..cs-1 (take 12bp upstream)
                    up15 = seq[max(0,cs-16):cs-1] if name=='+' else rc(seq)[L-ce: L-ce+15]
                    score = sum(1 for m in ['AGG','GGA','AGGT','GGTG','AAGGA','AGGAG'] if m in up15)
                    if score > 0: best.append((score, name, cs, ce, k-j))
for b in sorted(best, reverse=True)[:15]:
    print('SDscore', b[0], 'strand', b[1], 'nt', b[2],'-',b[3], 'aa_len', b[4])
